      u191: '. С каждым помощником по-прежнему можно общаться напрямую.',
      u192: 'Помощники работают параллельно и согласованно.',
      u193: 'Напрямую обсуждают решения, договариваются, кто за что отвечает, и передают друг другу файлы, отчёты и схемы для дальнейшей работы.',
      u194: 'Вы остаётесь на связи.',
      u195: 'Уточняете условия, добавляете задачи и меняете приоритеты по ходу дела — через координатора или напрямую с отдельным помощником.',
      u196: 'Подключаете возможности других инструментов и компьютеров.',
      u197: 'Помощники в разных AI-приложениях (Codex/ChatGPT, OpenCode, Cursor) и на компьютерах локальной сети используют свои инструменты и обмениваются результатами тем же способом.',
      u198: 'Масштаб определяет ваша задача.',
