      u238: 'Отклонён',
      u239: 'Для следующего этапа',
      u240: 'Сначала реализовать хранение источников и связей. Экспорт добавлять после проверки обновлений: иначе разные подборки начнут расходиться.',
      u241: 'Презентация',
      u242: 'Отчёт',
      u243: 'Порядок обновления',
      u244: 'Ответственный исправляет данные в источнике.',
