      u246: 'Презентация и отчёт получают обновлённые значения.',
      u247: 'Перед отправкой сохраняется снимок версии.',
      u248: 'Так уже отправленный файл остаётся неизменным, а новая подборка использует актуальные данные.',
      u249: '1. Выбрать папку проекта',
      u250: 'Новый шаг перед первым запуском: указать папку для хранения материалов. Если в папке уже есть проект, показать его название до подтверждения.',
      u251: '2. Подключить исходные данные',
      u252: 'В настройках открыть «Источники», нажать «Добавить файл» и выбрать таблицу. После загрузки проверить названия столбцов и дату данных.',
