      u157: 'La documentation est presque prête. Il me reste à ajouter les résultats des vérifications Windows.',
      u158: 'Ben → Kate',
      u159: 'Les vérifications sont terminées. J’ai transmis à Amy l’explication et une capture de la fenêtre.',
      u160: 'Terminez donc la section commune d’abord. Je vais réunir les ressources pour la suite.',
      u161: 'Kate convient de la prochaine étape avec Amy',
      u162: 'C’est convenu : Amy termine la documentation et dispose déjà des documents de Ben. Je prépare la suite. À votre retour, nous repartirons des résultats prêts.',
      u163: 'Tout pour commencer',
