      u176: 'Utilisation, instructions techniques et référence pour l’IA.',
      u177: 'Ouvrir llms.txt',
      u178: 'Vous connaissez déjà le sujet ? MAX mode',
      u179: 'Travaillez dans votre application IA habituelle.',
      u180: 'Codex/ChatGPT, OpenCode, Cursor — avec vos abonnements et vos outils. Lancez un projet, menez plusieurs tâches ou reprenez des travaux antérieurs.',
      u181: 'Donnez un nom à l’assistant dans l’onglet voulu.',
      u182: '« Connecte-toi en tant qu’agent Amy »',
      u183: '. Ce nom renvoie à cette discussion précise, à son travail, ses ressources et ses décisions.',
      u184: 'Réunissez les spécialistes adaptés à la tâche.',
