      u190: '« Tu es l’agent Joe, coordinateur. Accorde-toi sur le plan avec Amy et Ben, répartis le travail et suis les résultats »',
      u191: '. Vous gardez la possibilité de parler directement à chaque assistant.',
      u192: 'Les assistants avancent en parallèle et se coordonnent.',
