      u248: 'Le fichier déjà envoyé reste inchangé, tandis qu’une nouvelle sélection utilise les données à jour.',
      u249: '1. Choisir le dossier du projet',
      u250: 'Nouvelle étape avant le premier démarrage : choisir le dossier où seront conservées les ressources. Si un projet s’y trouve déjà, afficher son nom avant confirmation.',
      u251: '2. Connecter les données sources',
      u252: 'Dans les réglages, ouvrir « Sources », choisir « Ajouter un fichier » et sélectionner un tableau. Après le chargement, vérifier les noms des colonnes et la date des données.',
      u253: 'Points à vérifier pour la rédaction du guide',
      u254: 'Les noms des éléments correspondent à la version actuelle.',
      u255: 'Le choix du fichier est expliqué séparément pour Windows et macOS.',
      u256: 'L’exemple montre comment vérifier que le fichier a bien été chargé.',
      u257: '1. Installation',
      u258: 'Ouvrez le programme d’installation et terminez l’installation. Au premier démarrage, choisissez un dossier de projet. Vérifiez le nom du projet avant de confirmer.',
      u259: '2. Première source',
      u260: 'Ouvrez « Sources » → « Ajouter un fichier ». Choisissez le tableau des ressources. Son nom, sa date et son nombre de lignes apparaissent dans la liste : comparez-les avec l’original.',
      u261: '3. Première sélection',
      u262: 'Créez une sélection pour la prochaine réunion. Ajoutez les ressources utiles, vérifiez les liens vers les sources et enregistrez une version avant de l’envoyer.',
      u263: '4. Mise à jour',
      u264: 'Quand les données changent, mettez la source à jour. Consultez les ressources liées et enregistrez une nouvelle version de la sélection.',
      u265: 'Note de rédaction : compléter la section du choix du fichier avec des captures Windows et macOS après vérification par Ben.',
      u266: 'Vérification de la nouvelle version sur Windows',
      u267: 'Vérification',
      u268: 'Se termine sans erreur',
      u269: 'Le choix du projet s’ouvre',
      u270: 'Dossier du projet',
