      u272: 'Fenêtre système séparée, contrairement à macOS',
      u273: 'Chargement d’un tableau',
      u274: 'Le nom, la date et les lignes s’affichent',
      u275: 'À ajouter au guide',
      u276: 'Expliquer le choix du fichier séparément pour chaque système. Sur Windows, l’utilisateur confirme avec « Ouvrir » dans une fenêtre séparée, puis revient aux réglages de l’application.',
      u277: 'Pièce jointe au rapport :',
      u278: 'windows-file-picker.svg.',
      u279: 'Choisir les données sources',
