      u315: 'Tout afficher : travail en commun',
      u316: 'Rejouer : travail en commun',
      u317: 'Les agents d’OpenCode sur Windows et de Codex sur macOS échangent des messages et des fichiers. Joe coordonne les spécialistes.',
      u318: 'Une source envoie une mise à jour à la base commune, puis à la présentation et au rapport',
