      u331: 'Reprendre',
      u332: 'Activer l’animation',
      u333: 'Agents working together across OpenCode and Codex',
      u334: 'Windows runs OpenCode with Amy, Ben and Joe. macOS runs Codex with Kate, Max and Sam. Joe coordinates five connections. Separate opposing arrows show two-way communication with Amy and Kate. Ben and Sam send results to Joe; Joe sends tasks to Max. Kate sends materials to Max, and Max to Sam. Parcel icons mark transfers from Ben to Amy and Sam.',
