      u240: 'Bauen Sie zuerst den Speicher für Quellen und ihre Verknüpfungen. Fügen Sie den Export erst hinzu, nachdem Aktualisierungen getestet wurden; sonst können die Sammlungen auseinanderlaufen.',
      u241: 'Präsentation',
      u242: 'Bericht',
      u243: 'Ablauf der Aktualisierung',
      u244: 'Der Verantwortliche korrigiert die Daten an der Quelle.',
      u245: 'Die Bibliothek erfasst die neue Version und die Liste verbundener Materialien.',
      u246: 'Präsentation und Bericht erhalten die aktualisierten Werte.',
