      u248: 'Die bereits versandte Datei bleibt unverändert, während eine neue Sammlung die aktuellen Daten nutzt.',
      u249: '1. Projektordner auswählen',
      u250: 'Neuer Schritt vor dem ersten Start: Wählen Sie den Ordner, in dem die Materialien gespeichert werden. Enthält er bereits ein Projekt, zeigen Sie dessen Namen vor der Bestätigung an.',
      u251: '2. Quelldaten verbinden',
      u252: 'Öffnen Sie in den Einstellungen „Quellen“, wählen Sie „Datei hinzufügen“ und dann eine Tabelle. Prüfen Sie nach dem Laden die Spaltennamen und das Datendatum.',
      u253: 'Was die Person prüfen sollte, die die Anleitung schreibt',
      u254: 'Die Bezeichnungen der Bedienelemente entsprechen der aktuellen Version.',
      u255: 'Die Dateiauswahl wird für Windows und macOS getrennt erklärt.',
      u256: 'Das Beispiel zeigt, wie das erfolgreiche Laden der Datei bestätigt wird.',
      u257: '1. Installation',
      u258: 'Öffnen Sie das Installationsprogramm und schließen Sie die Installation ab. Wählen Sie beim ersten Start einen Projektordner. Prüfen Sie vor dem Bestätigen den Projektnamen.',
      u259: '2. Erste Quelle',
      u260: 'Öffnen Sie „Quellen“ → „Datei hinzufügen“. Wählen Sie die Tabelle mit den Materialien. Dateiname, Datum und Zeilenzahl erscheinen in der Liste; vergleichen Sie sie mit dem Original.',
      u261: '3. Erste Sammlung',
      u262: 'Erstellen Sie eine Sammlung für die nächste Besprechung. Fügen Sie die benötigten Materialien hinzu, prüfen Sie die Quellenverweise und speichern Sie vor dem Teilen eine Version.',
      u263: '4. Aktualisierung',
      u264: 'Wenn sich die Daten ändern, aktualisieren Sie die Quelle. Prüfen Sie die verbundenen Materialien und speichern Sie eine neue Version der Sammlung.',
      u265: 'Redaktionshinweis: Nach der Prüfung durch Ben Screenshots von Windows und macOS zum Abschnitt über die Dateiauswahl hinzufügen.',
