      u249: '1. Scegli una cartella di progetto',
      u250: 'Nuovo passaggio prima del primo avvio: scegli la cartella in cui conservare i materiali. Se contiene già un progetto, mostrane il nome prima della conferma.',
      u251: '2. Collega i dati originali',
      u252: 'Nelle impostazioni apri «Fonti», seleziona «Aggiungi file» e scegli un foglio di calcolo. Una volta caricato, controlla i nomi delle colonne e la data dei dati.',
      u253: 'Cosa deve controllare chi scrive la guida',
      u254: 'I nomi dei comandi corrispondono alla versione attuale.',
      u255: 'La selezione del file è spiegata separatamente per Windows e macOS.',
      u256: 'L’esempio mostra come verificare che il file sia stato caricato correttamente.',
      u257: '1. Installazione',
      u258: 'Apri il programma di installazione e completa la procedura. Al primo avvio scegli una cartella di progetto. Controlla il nome del progetto prima di confermare.',
      u259: '2. Prima fonte',
      u260: 'Apri «Fonti» → «Aggiungi file». Scegli il foglio di calcolo dei materiali. Nome del file, data e numero di righe appariranno nell’elenco; confrontali con l’originale.',
      u261: '3. Prima raccolta',
      u262: 'Crea una raccolta per la prossima riunione. Aggiungi i materiali necessari, controlla i collegamenti alle fonti e salva una versione prima di condividerla.',
      u263: '4. Aggiornamento',
      u264: 'Quando i dati cambiano, aggiorna la fonte. Esamina i materiali collegati e salva una nuova versione della raccolta.',
      u265: 'Nota redazionale: aggiungere schermate Windows e macOS alla sezione sulla selezione dei file dopo la revisione di Ben.',
