      u160: 'Terminemos primero la sección compartida. Yo reuniré los materiales para la siguiente etapa.',
      u161: 'Kate acuerda el siguiente paso con Amy',
      u162: 'De acuerdo: Amy está terminando la documentación y ya tiene los materiales de Ben. Prepararé la siguiente etapa. Cuando vuelvas, podremos continuar a partir de los resultados terminados.',
      u163: 'Todo lo que necesitas para empezar',
