      u179: 'Trabaja en tu aplicación de IA habitual.',
      u180: 'Codex/ChatGPT, OpenCode, Cursor: con las suscripciones y herramientas que ya usas. Inicia un proyecto, gestiona varias tareas o retoma un trabajo anterior.',
      u181: 'Ponle un nombre a un asistente en la pestaña adecuada.',
