      u154: 'Ben、Windowsの確認は終わった？ Amyに何を渡したか教えて。',
      u155: 'KateがAmyとBenに進捗を確認します',
      u156: 'Amy → Kate',
      u157: 'ドキュメントはほぼ完成しているよ。あとはWindowsの確認結果を追加するだけ。',
      u158: 'Ben → Kate',
      u159: '確認は終わってる。説明とウィンドウのスクリーンショットをAmyに送ったよ。',
      u160: 'では、先に共通の説明を仕上げて。こちらは次の段階に必要な資料を集めておくね。',
      u161: 'KateがAmyと次の手順を相談します',
      u162: '決まりました。Amyがドキュメントを仕上げていて、Benの資料も届いています。私は次の段階を準備します。戻ってきたら、できあがった成果から続きを進められます。',
      u163: '始めるための情報',
      u164: '01',
      u165: 'インストールと接続',
      u166: 'いつものAIアプリに接続を設定して、メッセージのやり取りを始めましょう。',
      u167: 'セットアップガイド',
      u168: '02',
      u169: '対応アプリと、それぞれの接続方法。',
      u170: 'アプリ別ガイド',
      u171: '03',
      u172: '設定とモニタリング',
      u173: '接続、確認できるメッセージとファイルの履歴、エージェントに関する機能。',
      u174: '04',
      u175: '詳しいドキュメント',
      u176: '使い方、技術的な手順、AI向けリファレンス。',
      u177: 'llms.txtを開く',
      u178: '仕組みがわかる方へ — MAX mode',
      u179: 'いつものAIアプリで作業します。',
      u180: 'Codex/ChatGPT、OpenCode、Cursor。すでに使っている契約プランとツールで、プロジェクトを始めたり、複数の課題を進めたり、以前の作業を再開したりします。',
      u181: '目的のタブのアシスタントに名前を付けます。',
      u182: '「エージェント Amy として接続して」',
      u183: '。その名前には、このチャット、この作業、資料、決定事項が結びついています。',
      u184: '課題に合う専門家をそろえます。',
      u185: 'それぞれに役割、SKILL、名前を設定します。',
      u186: '「あなたはエージェント Amy、開発者。SKILL /ui-dev」',
      u187: '。',
      u188: '「あなたはエージェント Ben、テスター。SKILL /qa」',
      u189: '自分で仕事を割り振るか、調整役に任せます。',
      u190: '「あなたはエージェント Joe、調整役。AmyとBenと計画をすり合わせ、仕事を割り振り、成果を確認して」',
      u191: '。引き続き、どのアシスタントとも直接話せます。',
      u192: 'アシスタントは並行して、足並みをそろえて作業します。',
      u193: '判断を直接相談し、担当を決め、ファイルやレポート、図を交換して次の作業につなげます。',
      u194: 'あなたもつながったままです。',
      u195: '途中で条件を詳しく伝えたり、仕事を追加したり、優先順位を変えたりできます。調整役を通しても、各アシスタントに直接伝えてもかまいません。',
      u196: 'ほかのアプリやコンピューターのツールも使います。',
      u197: '異なるAIアプリ（Codex/ChatGPT、OpenCode、Cursor）やローカルネットワーク上のコンピューターのアシスタントが、それぞれのツールを使い、同じように成果を交換します。',
      u198: '規模は課題に合わせます。',
      u199: '一度だけ助けを求める場合も、複数の作業を並行して進める場合も、数週間にわたるプロジェクトも。仕事が複雑になっても、やり取りはシンプルなままです。',
      u200: 'これからも、自分のやり方で',
      u201: 'NCF Agent Interconnectをインストールし、AIアプリを接続して、アシスタントに名前を付けましょう。',
      u202: 'NCF Agent Interconnectをダウンロード',
