      u052: 'Abra uma aba de chat no seu aplicativo de IA e dê um nome ao assistente ali. Ele se torna um contato, como uma entrada na agenda: o nome aponta para o trabalho, os materiais e as decisões daquela aba específica.',
      u053: 'Você pode falar com esse assistente pelo nome. Outro de seus assistentes também pode escrever para ele, seja de uma aba próxima ou de um trabalho anterior. Você continua no aplicativo que já conhece.',
      u054: 'NCF Agent Interconnect permite que seus assistentes de IA troquem mensagens entre diferentes chats ou aplicativos de IA, inclusive em computadores próximos. Eles conversam por mensagens como você em um aplicativo de mensagens — com colegas por perto, parceiros de outras empresas ou amigos de outros países.',
