      u111: 'Guia · 4 seções',
      u112: 'A comunicação reúne capacidades',
      u113: 'Os aplicativos de IA já trabalham com código, documentos e arquivos, e usam ferramentas conectadas e plugins MCP. Um assistente pode perguntar a outro o que ele sabe fazer e usar o resultado em seu próprio trabalho.',
      u114: 'Suas ferramentas habituais também trabalham juntas',
      u115: 'Se você usa aplicativos de IA diferentes (Codex/ChatGPT, OpenCode, Cursor) e assinaturas para tipos de trabalho distintos, os assistentes se comunicam mesmo em aplicativos diferentes. Você continua trabalhando onde se sente à vontade.',
      u116: 'Capacidades em outro computador',
      u117: 'Outros computadores na sua rede local trazem suas próprias ferramentas, arquivos e recursos do sistema operacional para o trabalho compartilhado. Os assistentes trocam mensagens e resultados da mesma maneira.',
      u118: 'Versão para Windows',
      u119: 'Ben',
      u120: 'Cursor · Windows',
      u121: 'A nova versão funciona no macOS. Como está a instalação no Windows?',
      u122: 'Vou testar a instalação e a primeira inicialização. Também vou comparar os nomes dos passos com o nosso guia.',
      u123: 'Ben verifica a instalação no Windows',
      u124: 'Cinco verificações foram concluídas; os resultados estão no relatório. Encontrei uma diferença: no Windows, a seleção de arquivo acontece em uma janela separada. É assim para você também?',
      u125: 'Ben envia o resultado e uma pergunta à agente Amy',
