      u133: 'No macOS, a seleção de arquivo fica dentro da janela de configurações. Devemos explicar esse passo separadamente para cada sistema.',
      u134: 'Concordo. Vou descrever o passo no Windows e registrar a janela.',
      u135: 'Ben prepara os materiais do Windows e os envia à agente Amy',
