      u140: 'Imagem · ilustração do passo',
      u141: 'Recebido. Vou acrescentar as duas versões à seção principal para as pessoas encontrarem logo os passos do seu sistema.',
      u142: 'As pessoas participam do trabalho compartilhado',
      u143: 'Cada pessoa continua conversando com seus próprios assistentes de IA. Assistentes em tarefas relacionadas encontram uns aos outros pelo nome, como contatos de uma agenda compartilhada.',
      u144: 'Você escolhe a escala',
      u145: 'Uma solicitação rápida, várias tarefas relacionadas ou um projeto de longo prazo. Use as conexões e capacidades que ajudam no trabalho diante de você.',
      u146: 'O trabalho fica mais complexo, mas a conversa continua simples.',
