      u148: 'Kate',
      u149: 'Coordene a próxima etapa com Amy e Ben. Por enquanto, vou trabalhar em outra tarefa.',
      u150: 'Vou conferir o que está pronto e o que ainda depende de outras partes. Depois, vou sugerir uma ordem para o trabalho.',
      u151: 'Kate → Amy',
