      u176: 'Uso, instruções técnicas e referência para IA.',
      u177: 'Abrir llms.txt',
      u178: 'Já conhece o caminho? Modo MAX',
      u179: 'Trabalhe no seu aplicativo de IA habitual.',
      u180: 'Codex/ChatGPT, OpenCode, Cursor — com as assinaturas e ferramentas que você já usa. Comece um projeto, gerencie várias tarefas ou retome um trabalho anterior.',
      u181: 'Dê um nome a um assistente na aba certa.',
      u182: '“Conecte-se como agente Amy”',
      u183: '. Esse nome aponta para este chat exato, seu trabalho, seus materiais e suas decisões.',
      u184: 'Reúna especialistas para a tarefa.',
      u185: 'Dê a cada um um papel, uma SKILL e um nome.',
      u186: '“Você é a agente Amy, desenvolvedora. SKILL /ui-dev”',
      u187: '.',
      u188: '“Você é o agente Ben, testador. SKILL /qa”',
      u189: 'Distribua as tarefas por conta própria ou peça a um coordenador que faça isso.',
      u190: '“Você é o agente Joe, o coordenador. Combine o plano com Amy e Ben, distribua o trabalho e acompanhe os resultados”',
      u191: '. Você ainda pode falar diretamente com cada assistente.',
      u192: 'Os assistentes trabalham em paralelo e se mantêm sincronizados.',
      u193: 'Eles discutem decisões diretamente, combinam quem cuida de cada parte e passam arquivos, relatórios e diagramas para a próxima etapa.',
      u194: 'Você continua em contato.',
      u195: 'Esclareça requisitos, adicione tarefas e mude prioridades enquanto o trabalho avança, pelo coordenador ou diretamente com um assistente.',
      u196: 'Use ferramentas de outros aplicativos e de outros computadores.',
      u197: 'Assistentes de diferentes aplicativos de IA (Codex/ChatGPT, OpenCode, Cursor) e de computadores na sua rede local usam suas próprias ferramentas e trocam resultados da mesma forma.',
      u198: 'Sua tarefa determina a escala.',
