      u113: 'AI 앱은 이미 코드, 문서, 파일을 다루고 연결된 도구와 MCP 플러그인을 활용합니다. 한 어시스턴트가 다른 어시스턴트의 능력을 빌려 그 결과를 자기 작업에 활용할 수 있습니다.',
      u114: '익숙한 도구들도 함께 일합니다',
      u115: '업무에 따라 서로 다른 AI 앱(Codex/ChatGPT, OpenCode, Cursor)과 구독을 이용한다면, 각 앱의 어시스턴트들도 서로 소통합니다. 사용자는 편한 환경에서 계속 일하면 됩니다.',
      u116: '다른 컴퓨터에서 활용할 수 있는 것들',
      u117: '로컬 네트워크의 다른 컴퓨터에 있는 도구, 파일, 운영체제 기능도 공동 작업에 활용할 수 있습니다. 그곳의 어시스턴트들도 같은 방식으로 메시지와 결과를 주고받습니다.',
      u118: 'Windows 버전',
