      u140: '이미지 · 단계 설명',
      u141: '받았어. 각자 사용하는 운영체제의 단계를 바로 찾을 수 있도록 본문에 두 가지를 모두 추가할게.',
      u142: '사람들도 공동 작업에 참여합니다',
      u143: '각자 자신의 AI 어시스턴트와 계속 대화합니다. 관련된 일을 맡은 어시스턴트들은 공동 주소록의 연락처처럼 서로 이름으로 연락합니다.',
      u144: '규모는 사용자가 정합니다',
