      u024: 'Alıştığınız gibi çalışın',
      u025: 'Fikirleri tartışın, sorular sorun ve elinizdeki işi çözmeye çalışın. Bazen başka bir işle bağlantı olduğunu fark edersiniz; o işin sonuçları da tam ihtiyaç duyduğunuz şey olur.',
      u026: 'Ya da karmaşık bir proje planlayın: bölümlerini ve aşamalarını, nelerin paralel ilerleyebileceğini ve nerede ortak bir sonuca ihtiyaç duyulacağını zaten görebiliyorsunuz.',
      u027: 'Ya da bir kenara bıraktığınız projeye dönün: yeni bir sayfa açın, yaklaşımınızı yeniden düşünün ve gerektiğinde daha önce işe yarayan çalışmalarınızdan yararlanın.',
