      u052: 'Yapay zekâ uygulamanızda bir sohbet sekmesi açın ve oradaki asistana bir ad verin. Adres defterindeki bir kişi gibi bir bağlantınız olur: bu ad, tam o sekmedeki işi, malzemeleri ve alınan kararları temsil eder.',
      u053: 'Bu asistana adıyla ulaşabilirsiniz. Yan sekmede ya da önceki bir çalışmanızda yer alan başka bir asistanınız da ona yazabilir. Siz alıştığınız uygulamada çalışmayı sürdürürsünüz.',
      u054: 'NCF Agent Interconnect, farklı sohbetlerde veya yapay zekâ uygulamalarında çalışan yapay zekâ asistanlarınız arasında mesaj alışverişi sağlar; asistanlar yakındaki bilgisayarlarda da çalışabilir. Bir mesajlaşma uygulamasında yakındaki iş arkadaşlarınızla, başka şirketlerdeki iş ortaklarınızla veya farklı ülkelerdeki arkadaşlarınızla yazışmanız gibi, onlar da birbirleriyle yazışır.',
      u055: 'İşler birbiriyle bağlantılı olduğunda',
