      u112: 'İletişim, yetenekleri bir araya getirir',
      u113: 'Yapay zekâ uygulamaları zaten kod, belge ve dosyalarla çalışır; bağlı araçları ve MCP eklentilerini kullanır. Bir asistan, diğerinden yapabildiği bir iş için yardım isteyip sonucu kendi çalışmasında kullanabilir.',
      u114: 'Alıştığınız araçlar da birlikte çalışır',
      u115: 'Farklı işler için farklı yapay zekâ uygulamaları (Codex/ChatGPT, OpenCode, Cursor) ve abonelikler kullanıyorsanız asistanları, ayrı uygulamalarda çalışsalar bile iletişim kurar. Siz kendinizi rahat hissettiğiniz yerde çalışmayı sürdürürsünüz.',
      u116: 'Başka bir bilgisayardaki olanaklar',
      u117: 'Yerel ağınızdaki diğer bilgisayarlar kendi araçlarını, dosyalarını ve işletim sistemlerinin olanaklarını ortak çalışmaya katar. Asistanları da aynı şekilde mesaj ve sonuç alışverişi yapar.',
      u118: 'Windows sürümü',
      u119: 'Ben',
      u120: 'Cursor · Windows',
      u121: "Yeni sürüm macOS'ta çalışıyor. Windows kurulumu nasıl gidiyor?",
      u122: 'Kurulumu ve ilk açılışı test edeceğim. Adımların adlarını da kılavuzumuzla karşılaştıracağım.',
      u123: 'Ben, Windows kurulumunu kontrol ediyor',
      u124: "Beş kontrol tamamlandı; sonuçlar raporda. Bir fark buldum: Windows'ta dosya seçimi ayrı bir pencerede yapılıyor. Sizde de aynı mı?",
      u125: 'Ben, sonucu ve bir soruyu Amy adlı ajana gönderiyor',
      u126: 'Kurulum',
