      u132: 'Rapor · 5 kontrol',
      u133: "macOS'ta dosya seçimi ayarlar penceresine gömülü. Bu adımı her sistem için ayrı açıklamalıyız.",
      u134: 'Anlaştık. Windows adımını yazıp pencerenin ekran görüntüsünü alacağım.',
      u135: 'Ben, Windows malzemelerini hazırlayıp Amy adlı ajana gönderiyor',
      u136: 'Dosya seçimi',
