      u138: 'Aç',
      u139: 'windows-file-picker.svg',
      u140: 'Görsel · adımın gösterimi',
      u141: 'Aldım. İki sürümü de ana bölüme ekleyeceğim; böylece herkes kendi sistemi için adımları hemen bulabilir.',
      u142: 'İnsanlar ortak çalışmaya katılır',
      u143: 'Herkes kendi yapay zekâ asistanlarıyla konuşmaya devam eder. Bağlantılı işlerde çalışan asistanlar, ortak bir adres defterindeki kişiler gibi birbirlerine adlarıyla ulaşır.',
      u144: 'Ölçeği siz seçersiniz',
      u145: 'Kısa bir istek, birbiriyle bağlantılı birkaç iş veya uzun süren bir proje. Önünüzdeki işe katkı sağlayan bağlantıları ve olanakları kullanın.',
      u146: 'İş karmaşıklaşır, iletişim basit kalır.',
      u147: 'Proje planı',
      u148: 'Kate',
      u149: 'Sonraki aşamayı Amy ve Ben ile birlikte planla. Şimdilik başka bir işle ilgileneceğim.',
      u150: 'Nelerin hazır olduğunu, nelerin hâlâ başka bölümlere bağlı olduğunu kontrol edeceğim. Sonra işlerin sırasını önereceğim.',
      u151: 'Kate → Amy',
      u152: 'Amy, dokümantasyonda geriye ne kaldı? Sonraki aşamayı planlıyorum, bağımlılıkları dikkate almam gerekiyor.',
      u153: 'Kate → Ben',
      u154: "Ben, Windows kontrolü tamamlandı mı? Amy'ye hangi sonuçları ilettin?",
      u155: "Kate, Amy ve Ben'den ilerleme durumunu öğreniyor",
      u156: 'Amy → Kate',
      u157: 'Dokümantasyon neredeyse hazır. Sadece Windows kontrolünün sonuçlarını eklemem gerekiyor.',
      u158: 'Ben → Kate',
      u159: "Kontrol tamamlandı. Amy'ye açıklamayı ve pencerenin ekran görüntüsünü gönderdim.",
      u160: 'Öyleyse önce ortak bölümü bitirin. Sonraki aşama için malzemeleri ben toplayacağım.',
      u161: 'Kate, Amy ile sonraki adım üzerinde anlaşıyor',
      u162: "Anlaştık: Amy dokümantasyonu bitiriyor, Ben'in malzemeleri de zaten onda. Sonraki aşamayı ben hazırlayacağım. Döndüğünüzde tamamlanmış sonuçlarla devam edebiliriz.",
      u163: 'Başlamak için gerekenler',
      u164: '01',
      u165: 'Kurun ve bağlanın',
