      u172: 'Ayarlar ve izleme',
      u173: 'Bağlantılar, erişilebilir mesaj ve dosya geçmişi, ajanlarla çalışmaya yönelik özellikler.',
      u174: '04',
      u175: 'Tüm dokümantasyon',
      u176: 'Kullanım, teknik talimatlar ve yapay zekâ için başvuru kaynağı.',
