      u178: 'Nasıl çalıştığını zaten biliyor musunuz? MAX mode',
      u179: 'Alıştığınız yapay zekâ uygulamasında çalışın.',
      u180: 'Codex/ChatGPT, OpenCode, Cursor — zaten kullandığınız abonelikler ve araçlarla. Bir projeye başlayın, birden fazla işi yürütün veya önceki çalışmalarınıza dönün.',
      u181: 'Doğru sekmedeki asistana bir ad verin.',
      u182: '“Amy adlı ajan olarak bağlan”',
      u183: '. Bu ad, tam olarak bu sohbeti, işi, malzemeleri ve kararları temsil eder.',
      u184: 'İşe uygun uzmanları bir araya getirin.',
      u185: 'Her birine bir rol, bir SKILL ve bir ad verin.',
      u186: '“Sen Amy adlı ajansın, bir geliştiricisin. SKILL /ui-dev”',
      u187: '.',
      u188: '“Sen Ben adlı ajansın, bir test uzmanısın. SKILL /qa”',
      u189: 'İşleri kendiniz dağıtın ya da bir koordinatöre bırakın.',
      u190: '“Sen Joe adlı ajansın, koordinatörsün. Amy ve Ben ile planı netleştir, işleri dağıt ve sonuçları takip et”',
      u191: '. Yine de her asistanla doğrudan konuşabilirsiniz.',
      u192: 'Asistanlar paralel ve uyum içinde çalışır.',
      u193: 'Kararları doğrudan tartışır, kimin neyi üstleneceğini kararlaştırır ve sonraki aşama için birbirlerine dosya, rapor ve şema gönderirler.',
      u194: 'Siz de iletişimde kalırsınız.',
      u195: 'Çalışma ilerlerken koordinatör üzerinden veya bir asistanla doğrudan konuşarak gereksinimleri netleştirin, yeni işler ekleyin ve öncelikleri değiştirin.',
      u196: 'Diğer uygulamalardaki ve bilgisayarlardaki araçları kullanın.',
      u197: 'Farklı yapay zekâ uygulamalarında (Codex/ChatGPT, OpenCode, Cursor) ve yerel ağınızdaki bilgisayarlarda çalışan asistanlar kendi araçlarını kullanıp aynı şekilde sonuç alışverişi yapar.',
      u198: 'Ölçeği işiniz belirler.',
      u199: 'Tek bir yardım isteği, paralel yürüyen birkaç iş veya haftalar süren bir proje. İş karmaşıklaşır, iletişim basit kalır.',
      u200: 'Kendi tarzınızda çalışmaya devam edin',
      u201: "NCF Agent Interconnect'i kurun, yapay zekâ uygulamanızı bağlayın ve asistanlarınıza ad verin.",
