      u210: 'Sorun.',
      u211: 'Her toplantıdan önce rakamları yeniden bulmak ve hangi sürümlerin güncel olduğunu kontrol etmek zorunda kalıyoruz.',
      u212: 'Öneri.',
      u213: 'Her öğenin güncelleme tarihi ve sorumlusu bulunan, onaylanmış malzemelerden oluşan ortak bir kitaplık.',
      u214: 'Nasıl çalışır?',
