      u177: 'Otwórz llms.txt',
      u178: 'Znasz już podstawy? Tryb MAX',
      u179: 'Pracuj w znanej aplikacji AI.',
      u180: 'Codex/ChatGPT, OpenCode, Cursor — z subskrypcjami i narzędziami, których już używasz. Rozpocznij projekt, prowadź kilka zadań albo wróć do wcześniejszej pracy.',
      u181: 'Nadaj asystentowi imię we właściwej karcie.',
      u182: '„Połącz się jako agent Amy”',
      u183: '. To imię prowadzi do dokładnie tego czatu, jego pracy, materiałów i decyzji.',
      u184: 'Zbierz specjalistów do zadania.',
      u185: 'Nadaj każdemu rolę, SKILL i imię.',
      u186: '„Jesteś agentką Amy, programistką. SKILL /ui-dev”',
      u187: '.',
      u188: '„Jesteś agentem Ben, testerem. SKILL /qa”',
      u189: 'Przydzielaj zadania samodzielnie albo poproś o to koordynatora.',
      u190: '„Jesteś agentem Joe, koordynatorem. Uzgodnij plan z Amy i Ben, przydziel pracę i śledź wyniki”',
      u191: '. Nadal możesz rozmawiać bezpośrednio z każdym asystentem.',
      u192: 'Asystenci pracują równolegle i pozostają w kontakcie.',
      u193: 'Bezpośrednio omawiają decyzje, uzgadniają odpowiedzialność i przekazują sobie pliki, raporty i diagramy do kolejnego etapu.',
      u194: 'Utrzymujesz kontakt.',
      u195: 'Doprecyzowuj wymagania, dodawaj zadania i zmieniaj priorytety w trakcie pracy — przez koordynatora albo bezpośrednio z asystentem.',
      u196: 'Korzystaj z narzędzi w innych aplikacjach i na innych komputerach.',
      u197: 'Asystenci w różnych aplikacjach AI (Codex/ChatGPT, OpenCode, Cursor) oraz na komputerach w Twojej sieci lokalnej używają własnych narzędzi i w ten sam sposób wymieniają wyniki.',
      u198: 'Twoje zadanie wyznacza skalę.',
      u199: 'Jedna prośba o pomoc, kilka równoległych zadań albo projekt trwający tygodniami. Praca staje się bardziej złożona, ale rozmowa pozostaje prosta.',
      u200: 'Pracuj dalej po swojemu',
