      u240: 'Najpierw zbuduj miejsce do przechowywania źródeł i ich powiązań. Dodaj eksport po przetestowaniu aktualizacji; w przeciwnym razie kolekcje mogą się rozjechać.',
      u241: 'Prezentacja',
      u242: 'Raport',
