      u249: '1. Wybierz folder projektu',
      u250: 'Nowy krok przed pierwszym uruchomieniem: wybierz folder do przechowywania materiałów. Jeśli folder zawiera już projekt, pokaż jego nazwę przed potwierdzeniem.',
      u251: '2. Podłącz dane źródłowe',
      u252: 'W ustawieniach otwórz „Źródła”, wybierz „Dodaj plik” i wskaż arkusz kalkulacyjny. Po wczytaniu sprawdź nazwy kolumn i datę danych.',
      u253: 'Co powinien sprawdzić autor przewodnika',
