      u260: 'Otwórz „Źródła” → „Dodaj plik”. Wybierz arkusz z materiałami. Na liście pojawią się nazwa pliku, data i liczba wierszy; porównaj je z oryginałem.',
      u261: '3. Pierwsza kolekcja',
      u262: 'Utwórz kolekcję na następne spotkanie. Dodaj potrzebne materiały, sprawdź odnośniki do źródeł i zapisz wersję przed udostępnieniem.',
