      u133: 'Op macOS is bestandskeuze ingebouwd in het instellingenvenster. We moeten deze stap voor elk systeem apart uitleggen.',
      u134: 'Afgesproken. Ik werk de Windows-stap uit en maak een schermafbeelding van het venster.',
