      u141: 'Ontvangen. Ik voeg beide varianten aan het hoofdonderdeel toe, zodat gebruikers direct de stappen voor hun systeem vinden.',
      u142: 'Mensen sluiten aan bij het gezamenlijke werk',
      u143: 'Iedereen blijft met zijn eigen AI-assistenten praten. Assistenten met samenhangende taken bereiken elkaar bij naam, zoals contacten in een gezamenlijk adresboek.',
      u144: 'Jij bepaalt de schaal',
      u145: 'Een snelle vraag, meerdere samenhangende taken of een langdurig project. Gebruik de verbindingen en mogelijkheden die helpen bij het werk dat nu voor je ligt.',
