      u249: '1. Een projectmap kiezen',
      u250: 'Nieuwe stap vóór de eerste start: kies de map waarin het materiaal wordt bewaard. Staat er al een project in de map, toon dan vóór de bevestiging de naam ervan.',
      u251: '2. Brongegevens koppelen',
      u252: 'Open in de instellingen “Bronnen”, kies “Bestand toevoegen” en selecteer een spreadsheet. Controleer na het laden de kolomnamen en de datum van de gegevens.',
